// Extract and validate webhook data
const webhook = $input.first().json;

// Only process issue update events
if (webhook.action !== 'update') {
  return { skip: true, reason: 'Not an update event' };
}

const issue = webhook.data?.issue;
if (!issue) {
  return { skip: true, reason: 'No issue data' };
}

const currentStatus = issue.state?.name;
const previousStatus = webhook.data?.fromState?.name;

// Only process if status actually changed
if (currentStatus === previousStatus) {
  return { skip: true, reason: 'Status unchanged' };
}

return {
  skip: false,
  issueId: issue.id,
  identifier: issue.identifier,
  title: issue.title,
  description: issue.description,
  currentStatus,
  previousStatus,
  assignee: issue.assignee?.name,
  project: {
    id: issue.project?.id,
    name: issue.project?.name
  },
  url: issue.url,
  labels: issue.labels?.nodes?.map(l => l.name) || [],
  webhook
};

// Backlog Status Prompt
const issue = $input.first().json;

const prompt = `You are a senior product manager analyzing a Linear issue that just moved to Backlog status.

Issue Details:
- Title: ${issue.title}
- Description: ${issue.description}
- Project: ${issue.project.name}
- Previous Status: ${issue.previousStatus}
- Labels: ${issue.labels.join(', ')}

Please analyze this issue and provide:

1. **Priority Assessment**: Evaluate urgency and importance
2. **Complexity Estimate**: Suggest story points (1, 2, 3, 5, 8, 13)
3. **Dependencies**: Identify potential blockers or prerequisites
4. **Acceptance Criteria Review**: Flag if acceptance criteria are missing or unclear
5. **Resource Planning**: Suggest optimal team member assignment
6. **Next Steps**: Recommend immediate actions

Provide a structured response that can be added as a comment to the Linear issue.`;

return {
  prompt,
  issueData: issue,
  statusType: 'backlog'
};

// In Progress Status Prompt
const issue = $input.first().json;

const prompt = `You are a technical lead analyzing a Linear issue that just moved to In Progress status.

Issue Details:
- Title: ${issue.title}
- Description: ${issue.description}
- Assignee: ${issue.assignee || 'Unassigned'}
- Project: ${issue.project.name}
- Previous Status: ${issue.previousStatus}

Please provide development guidance:

1. **Technical Approach**: Suggest implementation strategy
2. **Architecture Considerations**: Identify system impacts
3. **Testing Strategy**: Recommend testing approach
4. **Potential Risks**: Flag technical challenges
5. **Resource Requirements**: Estimate time and dependencies
6. **Definition of Done**: Clarify completion criteria

Provide actionable guidance for the developer to ensure successful implementation.`;

return {
  prompt,
  issueData: issue,
  statusType: 'in-progress'
};

// Ready for Test Cases Status Prompt
const issue = $input.first().json;

const prompt = `You are a QA specialist analyzing a Linear issue that is ready for test cases.

Issue Details:
- Title: ${issue.title}
- Description: ${issue.description}
- Project: ${issue.project.name}
- Previous Status: ${issue.previousStatus}

Please generate comprehensive test cases:

1. **Functional Test Cases**: Cover all acceptance criteria
2. **Edge Cases**: Identify boundary conditions
3. **Error Scenarios**: Test failure conditions
4. **User Experience Tests**: Validate user workflows
5. **Integration Tests**: Check system interactions
6. **Accessibility Tests**: Ensure compliance standards

Format each test case with:
- **Test Case ID**: TC-[number]
- **Description**: What is being tested
- **Prerequisites**: Setup requirements
- **Steps**: Detailed test steps
- **Expected Result**: What should happen
- **Priority**: High/Medium/Low

Generate 5-10 comprehensive test cases ready for QA execution.`;

return {
  prompt,
  issueData: issue,
  statusType: 'test-cases'
};

// In Review Status Prompt
const issue = $input.first().json;

const prompt = `You are a senior developer conducting a code review for a Linear issue in Review status.

Issue Details:
- Title: ${issue.title}
- Description: ${issue.description}
- Assignee: ${issue.assignee || 'Unknown'}
- Project: ${issue.project.name}
- Previous Status: ${issue.previousStatus}

Please provide code review guidance:

1. **Review Checklist**: Key areas to examine
2. **Quality Standards**: Code quality requirements
3. **Security Considerations**: Security review points
4. **Performance Impact**: Performance review criteria
5. **Documentation Requirements**: What docs need updating
6. **Testing Validation**: Required test coverage

Generate a structured code review checklist and key focus areas for reviewers to ensure high-quality code delivery.`;

return {
  prompt,
  issueData: issue,
  statusType: 'in-review'
};

// Done Status Prompt
const issue = $input.first().json;

const prompt = `You are a project manager analyzing a Linear issue that just completed (Done status).

Issue Details:
- Title: ${issue.title}
- Description: ${issue.description}
- Assignee: ${issue.assignee || 'Team'}
- Project: ${issue.project.name}
- Previous Status: ${issue.previousStatus}

Please provide completion analysis:

1. **Delivery Summary**: Summarize what was accomplished
2. **Success Metrics**: How to measure success
3. **Stakeholder Communication**: Key points to communicate
4. **Documentation Updates**: What needs to be updated
5. **Follow-up Actions**: Any required next steps
6. **Lessons Learned**: Key insights for future work

Generate a project completion summary and stakeholder communication template.`;

return {
  prompt,
  issueData: issue,
  statusType: 'done'
};

